---@class BeginnerAssembleAchievementDialog
---@field Env                           	BeginnerAssembleAchievementDialog       
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field ListView                      	SuperScrollView.LoopListView2           	@ 0    
---@field TextTime2                     	UnityEngine.RectTransform               	@ 1    
---@field FontStyleButton               	UnityEngine.RectTransform               	@ 2    
local BeginnerAssembleAchievementDialog = Class('BeginnerAssembleAchievementDialog')
---@type BeginnerUtils
local BeginnerUtils = import('Game.Activity.BeginnerAssemble.BeginnerUtils')
local TaskCellNodePath = "Game.Activity.BeginnerAssemble.Cell.BeginnerAssembleAchievementCell"


function BeginnerAssembleAchievementDialog:__init()

end

function BeginnerAssembleAchievementDialog:__delete()

end

function BeginnerAssembleAchievementDialog:RefreshTopGoods()

end


function BeginnerAssembleAchievementDialog:Awake()
	SetButtonAction(self.FontStyleButton,Bind(self,self.OnFontStyleBtnClick))
end

function BeginnerAssembleAchievementDialog:Refresh(config)
	self.config = config
	self.dojo = BeginnerUtils.GetBeginnerDojo()
	
	self.tasks = self.dojo.achievements
	self:SortAchievements(self.tasks)
	self:RefreshListShow()
end

function BeginnerAssembleAchievementDialog:RefreshListShow()
	if not self.ListView.IsListViewInit then
		self.ListView:InitListView(#self.tasks, Bind(self, self.OnGetItemByIndex))
	else
		GameUtils.ReloadData(self.ListView, 0)
		GameUtils.ReloadData(self.ListView, #self.tasks)
	end
end

function BeginnerAssembleAchievementDialog:OnGetItemByIndex(loopListView, index)
	if index < 0 then
		return nil
	end
	
	local cell = loopListView:NewListViewItem("BeginnerAssembleAchievementListCell")
	if not cell.IsInitHandlerCalled then
		cell.IsInitHandlerCalled = true
	end
	-- 这里一个cell是一个页面，一个页面有9个按钮
	local data = self.tasks[index + 1]
	if isNotNull(data) then
		---@type BeginnerAssembleWelfareCell
		local env = CfUtils.GetLuaScr(cell, TaskCellNodePath)
		if env then
			env:SetBtnCallBackGet(Bind(self, self.OnCellAction))
			env:FreshBaseUI(data)
			env:SetBtnCallBackJump(function()
				local isCompleted = data.progress >= data.taskContentNum
				if not isCompleted then
					if checkNumber(data.openType) == 0 then
						return
					end
					local goodsConfMgr = GoodsConfMgr:GetInstance()
					local row = goodsConfMgr:GetJumpModuleRow(data.openType)
					goodsConfMgr:ExecuteJump(row, {})
				end
			end)
		end
	end
	return cell
end

function BeginnerAssembleAchievementDialog:OnCellAction(cellData)
	---可领取的情况下
	GameUtils.Request(Interfaces.ActivityBeginnerDrawAchievement, { achievementId = cellData.id }, function(request, response)
		if checkNumber(response.errCode) == 0 then
			local rewards = response.data.rewards
			GoodsUtils.DrawRewards(rewards, true)
			---更新界面ui
			---@type BeginnerMgr
			local beginnerMgr = BeginnerUtils.GetBeginnerMgr()
			---@type BeginnerDojo
			local dojo = beginnerMgr:GetHomeDojo()
			for i, v in pairs(dojo.achievements) do
				if checkNumber(v.id) == checkNumber(cellData.id) then
					local taskVo = CfUtils.GetCfVo(AutoIds.IdSetting8936,"BeginnerAchievementTaskVo",v.id)
					v.hasDrawn = 1
					v.progress = math.max(taskVo.taskContenNum, v.progress)
				end
			end
			self:SortAchievements(dojo.achievements)
			----已领取的逻辑
			CfUtils.DialogOpen(Constants.UITypeIds.UICommonRewardPop, { rewards = rewards })
			BeginnerUtils.RefreshRedPoint(self.config.type)
			self:Refresh(self.config)
		end
	end)
end

function BeginnerAssembleAchievementDialog:SortAchievements(achievements)
	local hasDrawnAchievements = {}
	local completes = {}
	for i = #achievements , 1 , -1 do
		local achievement = achievements[i]
		if checkInt(achievement.hasDrawn) == 1 then
			hasDrawnAchievements[#hasDrawnAchievements+1] = table.remove(achievements , i )
		else 
			local taskVo = CfUtils.GetCfVo(AutoIds.IdSetting8936,"BeginnerAchievementTaskVo",achievement.id)
			local isCompleted = checkInt(achievement.progress) >= checkInt(taskVo.taskContenNum)  
			if isCompleted then
				completes[#completes+1] = table.remove(achievements, i)
			end
		end
	end
	for i =1 , #completes do
		table.insert(achievements,1,completes[i])
	end 
	table.insertto(achievements , hasDrawnAchievements)
end

function BeginnerAssembleAchievementDialog:RefreshTimeShow()
	local curTime = GameUtils.GetServerTime() or os.time()
	local time = math.max(0, BeginnerUtils.GetBeginnerMgr():GetHomeDojo().achievementLeftSeconds - curTime)
	CfUtils.FillText(self.TextTime2,CfUtils.GetTimeHMS4(time))
end

function BeginnerAssembleAchievementDialog:OnFontStyleBtnClick()
	local isCanOneKey = BeginnerUtils.GetBeginnerMgr():CheckAchievementRedPoint()
	if isCanOneKey then
		---可领取的情况下
		GameUtils.Request(Interfaces.ActivityBeginnerDrawAchievement, { achievementId = 0 }, function(request, response)
			if checkNumber(response.errCode) == 0 then
				local rewards = response.data.rewards
				GoodsUtils.DrawRewards(rewards, true)
				---更新界面ui
				---@type BeginnerMgr
				local beginnerMgr = BeginnerUtils.GetBeginnerMgr()
				---@type BeginnerDojo
				local dojo = beginnerMgr:GetHomeDojo()
				for i, v in pairs(dojo.achievements) do
					local taskVo = CfUtils.GetCfVo(AutoIds.IdSetting8936,"BeginnerAchievementTaskVo", v.id)
					local isCanDraw = (v.progress >= taskVo.taskContenNum)  and (v.hasDrawn ~= 1)
					if isCanDraw then
						v.hasDrawn = 1
						v.progress = math.max(taskVo.taskContenNum, v.progress)
					end
				end
				self:SortAchievements(dojo.achievements)
				----已领取的逻辑
				CfUtils.DialogOpen(Constants.UITypeIds.UICommonRewardPop, { rewards = rewards })
				BeginnerUtils.RefreshRedPoint(self.config.type)
				self:Refresh(self.config)
			end
		end)
	else
		GameUtils.Toast(localize("暂无可任务的任务"))
	end
end

function BeginnerAssembleAchievementDialog:OnDestroy()
	self.controller = nil--luabehaviour 中CSharp对象
	self:Delete()
end

return BeginnerAssembleAchievementDialog